bounded_host_request.command:
set -euo pipefail
image=create-videobot:local-poll
docker image inspect "$image" >/dev/null 2>&1 || exit 61
docker run --rm --network host --pull never --read-only --cap-drop ALL \
 --security-opt no-new-privileges:true --entrypoint node "$image" --input-type=module -e '
import dns from "node:dns/promises";
import https from "node:https";
import {setDefaultResultOrder} from "node:dns";
setDefaultResultOrder("ipv4first");
let ip;
try {ip=(await dns.lookup("api.telegram.org",{family:4})).address;}
catch{process.exit(80);}
const httpsOk=await new Promise(resolve=>{
 const r=https.get("https://api.telegram.org",{family:4,timeout:9000},x=>{
  x.resume();resolve(x.statusCode>=200&&x.statusCode<500);
 });
 r.on("error",()=>resolve(false));
 r.on("timeout",()=>{r.destroy();resolve(false)});
});
if(!httpsOk)process.exit(81);
try{
 const r=await fetch("https://api.telegram.org",{signal:AbortSignal.timeout(10000)});
 if(r.status>=200&&r.status<500)process.exit(0);
 process.exit(82);
}catch(e){
 const c=String(e?.cause?.code??e?.code??"");
 if(c==="ENOTFOUND"||c==="EAI_AGAIN")process.exit(83);
 if(c==="ETIMEDOUT"||c==="UND_ERR_CONNECT_TIMEOUT")process.exit(84);
 if(c==="ENETUNREACH"||c==="EHOSTUNREACH")process.exit(85);
 if(c==="ECONNREFUSED")process.exit(86);
 if(c.includes("CERT")||c.includes("TLS"))process.exit(87);
 process.exit(88);
}'
